// Retrieve input from JSON, fallback to an empty string if it's not defined
const data = $json.emails || '';

// Ensure input is a string
const inputString = Array.isArray(data) ? data.join(' ') : String(data);

// Improved regex to match emails and exclude image extensions like .png, .jpg, .gif, .jpeg
const emailRegex = /[a-zA-Z0-9._%+-]+@[a-zA-Z0-9.-]+\.(?!png|jpg|gif|jpeg)[a-zA-Z]{2,}/g;

// Match valid email addresses
let emails = inputString.match(emailRegex) || []; // Default to empty array if no match

// Deduplicate the email addresses
emails = [...new Set(emails)];

// Log output for debugging in n8n
console.log("Matched Emails:", emails);

// Limit the result to the first 5 email addresses
emails = emails.slice(0, 2);

// Return the cleaned list of emails in n8n-compatible format
return { json: { emails: emails } };

let emails = []; // Initialize emails as an empty array

try {
  // Extract data from input
  const data = $json.data;

  // Ensure data exists and is a string before proceeding
  if (typeof data === 'string') {
    // Define a regular expression to match email addresses
    const emailRegex = /[a-zA-Z0-9._%+-]+@[a-zA-Z0-9.-]+\.(?!png|jpg|gif|jpeg)[a-zA-Z]{2,}/g;

    // Use the regex to extract emails from the input data
    emails = data.match(emailRegex) || []; // Fallback to an empty array if no matches are found
  } else {
    console.log("Data is not a string. Skipping email extraction.");
  }
} catch (error) {
  // Handle and log any unexpected errors
  console.error("An error occurred during email extraction:", error.message);
}

// Log the extracted emails for debugging purposes
console.log("Extracted Emails:", emails);

// Return the result in the desired format
return {
  json: {
    emails: emails // Return the array of emails (even if empty due to errors)
  }
};

// Alternative approach that works in most n8n versions
const items = [];

// Get all input items
const inputItems = Array.isArray($input) ? $input : $input.items || [$input.item];

// Process each item
for (const item of inputItems) {
  // Get the social media data
  let socialMediaData = item.json.social_media;

  // Parse it if it's a string
  if (typeof socialMediaData === 'string') {
    socialMediaData = JSON.parse(socialMediaData);
  }

  // Create formatted output for this item
  const formattedSocialMedia = socialMediaData.map(platform => {
    return `${platform.platform}: ${platform.urls[0]}`;
  }).join('\n');

  // Add this processed item to our new array
  items.push({
    json: {
      ...item.json,
      formatted_social_media: formattedSocialMedia
    }
  });
}

// Return all processed items
return {items};

const items = $input.all();
const updatedItems = items.map(item => {
    item.json["Start Page"] = (item.json["start_page"] || 0) + 10;
    return item;
});
return updatedItems;

// Access the incoming array of data from the variable local_results
const dataArray = $input.item.json.local_results;

// Extract and clean the website and title properties from each object in the array
const results = dataArray
  .map(item => { 
    // Check if the website property exists and is a string
    const website = item.website && typeof item.website === 'string'
      ? item.website.split('?')[0] // Remove query parameters
        .replace(/\/$/, '') // Remove the trailing slash
      : null;

    // Check if the title property exists
    const company = item.title && typeof item.title === 'string' ? item.title : null;

    // Only return the result if the website is valid (not null or empty)
    if (website) {
      return { website, company };
    }

    // Skip entries without a valid website
    return null;
  })
  .filter(result => result !== null); // Remove any null values from the result

// Output the cleaned results as an array of objects
return {
  results,
};
